#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
#
# Run the jt51 conformance bench and compare it with the reference stream.
# RUN FROM ANYWHERE; it changes to the repository root itself.
#
#     scripts/sim_jt51.sh
#
# sim/jt51_tb/expected_con7.txt is the OPM reference for CON 7, OPMASK 1,
# TL 0, FL 0, 4462 samples, generated by jt51's own `bin/print_con`:
#
#     print_con CON 7 OPMASK 1 TL 0 FL 0 LEN 4462 | head -n 4462
#
# The bench prints one signed decimal sample per `sample` pulse. The chip
# emits samples before the tone is programmed; those leading zeros are
# dropped, which is the same filter the upstream C++ harness applied. Any
# non-zero value before the tone starts is therefore still a failure.
#
# docs/VENDOR_TESTS.md explains why the bench is a derived file rather than
# upstream's jt51_con.cc verbatim.
set -euo pipefail

cd "$(dirname "$0")/.."
[ -d sim/jt51_tb ] || { echo "no sim/jt51_tb"; exit 1; }

LOG=build/jt51_sim.log
OUT=build/jt51_sim.out
mkdir -p build

bash scripts/run_sim.sh jt51_tb > "$LOG" 2>&1 || { tail -30 "$LOG"; exit 1; }

awk '/dump start/{f=1;next} /dump end/{f=0} f' "$LOG" \
	| sed 's/^# *//' | grep -E '^-?[0-9]+$' \
	| awk '$0 != "0" { s=1 } s' > "$OUT"

exp=sim/jt51_tb/expected_con7.txt
if ! awk -v out="$OUT" '
	NR==FNR { a[NR] = $0; n = NR; next }
	FNR > n { print "extra sample at line " FNR ": " $0; bad = 1; exit }
	("" $0) != ("" a[FNR]) {
		print "mismatch at sample " FNR ": expected " a[FNR] ", got " $0
		bad = 1; exit
	}
	END {
		if (FNR != n) { print "sample count " FNR ", expected " n; bad = 1 }
		if (!bad) print "PASS: " n " samples match the OPM reference"
		exit bad
	}' "$exp" "$OUT"; then
	echo "jt51: FAIL"
	exit 1
fi
